UPDATE wine SET embedding_text_ko = '바인굿 크놀 리드 로이벤베르크 로이브너 리슬링 스마라그 2024는 오스트리아 Wachau에서 생산된 화이트 와인입니다. 100% Riesling 품종 기반으로, 과수원 과일: peach, apricot, pear, 흙내음: minerals, honey, stone, 시트러스 과일: lemon, citrus, lime의 향과 풍미가 두드러집니다. 묵직한 바디감, 산미가 높은 산미, 탄닌이 약한 탄닌, 드라이한 당도의 특징을 가지며, 에피타이저와 스낵, 매운 음식, 돼지고기, 해산물와 잘 어울립니다. 와인 스타일은 오스트리아n 리슬링로 분류됩니다.' WHERE name_en = 'Weingut Knoll Ried Loibenberg Loibner Riesling Smaragd 2024' OR name_kr = '바인굿 크놀 리드 로이벤베르크 로이브너 리슬링 스마라그 2024';
UPDATE wine SET embedding_text_ko = '도나푸가타 벨라사이 2016는 이탈리아 Sicilia에서 생산된 레드 와인입니다. 100% Frappato 품종 기반으로, 붉은 과실: strawberry, 체리, raspberry, 오크: 오크, 바닐라, 담배 잎, 향신료: 후추, licorice, anise의 향과 풍미가 두드러집니다. 묵직한 바디감, 산미가 적당히 살아 있는 산미, 탄닌이 존재감 있는 탄닌, 드라이한 당도의 특징을 가지며, 파스타, 소고기, 양고기와 잘 어울립니다. 와인 스타일은 Southern 이탈리아 Red로 분류됩니다.' WHERE name_en = 'Donnafugata Bell''Assai 2016' OR name_kr = '도나푸가타 벨라사이 2016';
UPDATE wine SET embedding_text_ko = '샤또 칼롱-세귀르 생테스테프 (그랑 크뤼 클래스) 2000는 프랑스 Saint-Estèphe에서 생산된 레드 와인입니다. 55% Cabernet Sauvignon, 35% Merlot, 10% Cabernet Franc 품종 기반으로, 오크: 담배 잎, 오크, cedar, 흙내음: leather, 흙내음, smoke, 검은 과실: 카시스, blackcurrant, 블랙베리의 향과 풍미가 두드러집니다. 묵직한 바디감, 산미가 높은 산미, 탄닌이 강한 탄닌, 드라이한 당도의 특징을 가지며, 사냥육, 소고기, 양고기, 닭고기와 잘 어울립니다. 와인 스타일은 Bordeaux Saint-Estèphe로 분류됩니다.' WHERE name_en = 'Château Calon-Ségur Saint-Estèphe (Grand Cru Classé) 2000' OR name_kr = '샤또 칼롱-세귀르 생테스테프 (그랑 크뤼 클래스) 2000';
